import Fraction from "fraction.js";
export function puzzle(input){
  const m=input.matrix; const f=new Fraction(input.factor||1); const n=m.length;
  const A=Array(n);
  for(let i=0;i<n;i++){ A[i]=Array(n); for(let j=0;j<n;j++){ A[i][j]=new Fraction(m[i][j]||0); }}
  const resultTraces=[]; let P=A;
  for(let k=1;k<=n;k++){
    let t=new Fraction(0);
    for(let i=0;i<n;i++){ t=t.add(P[i][i]); }
    resultTraces.push(t.mul(f));
    const N=P.length; const Q=Array(N);
    for(let i=0;i<N;i++){ Q[i]=Array(N); for(let j=0;j<N;j++){ let sum=new Fraction(0);
        for(let r=0;r<N;r++){ sum=sum.add(P[i][r].mul(A[r][j])); }
        Q[i][j]=sum; }}
    P=Q;
  }
  const total=resultTraces.reduce((s,x)=>s.add(x),new Fraction(0));
  return {traces:resultTraces.map(x=>x.toFraction()),sum:total.toFraction()};
}
