def document_processor(input_data):
    def process_node(node, depth=0, path="root"):
        if depth > 5:
            return {"type": "max_depth"}

        if isinstance(node, dict):
            result = {}
            for k, v in sorted(node.items()):
                new_path = f"{path}.{k}"
                sig = sum(ord(c) for c in new_path) % 17
                result[k] = {
                    "sig": sig,
                    "data": process_node(v, depth+1, new_path)
                }
            return {"type": "dict", "size": len(node), "content": result}

        elif isinstance(node, list):
            result = []
            for i, item in enumerate(node[:8]):  # Limit to 8 items
                new_path = f"{path}[{i}]"
                result.append({
                    "idx": i,
                    "data": process_node(item, depth+1, new_path)
                })
            return {"type": "list", "length": len(node), "items": result}

        else:
            # Process primitive values
            if isinstance(node, str):
                attrs = {"len": len(node), "digits": any(c.isdigit() for c in node)}
            elif isinstance(node, int):
                attrs = {"even": node % 2 == 0, "pos": node > 0}
            else:
                attrs = {"type": str(type(node).__name__)}

            return {"type": "value", "value": node, "attrs": attrs}

    processed = process_node(input_data)
    processed["meta"] = {"complexity": get_complexity(input_data)}
    return processed

def get_complexity(data):
    if isinstance(data, dict):
        return min(10, len(data) + sum(get_complexity(v) for v in list(data.values())[:2]))
    elif isinstance(data, list):
        return min(10, len(data) + (get_complexity(data[0]) if data else 0))
    else:
        return 1
