export function optimizeStreamCharge(input) {
  const { metrics: M, stations: S, queue: Q, cycle: C } = input;
  const N = M.length;
  const W = N ? M[0].length : 0;
  const P = M.map((row, i) => row.map((v, j) => (v << 1) + S[i][j]));

  const assignments = Q.reduce((out, req) => {
    let [rx, ry] = req;
    let best = -Infinity;
    let pick = [0, 0];
    P.forEach((r, i) => r.forEach((base, j) => {
      const dist = Math.abs(i - rx) + Math.abs(j - ry);
      const score = base - (dist * 3);
      if (score > best) { best = score; pick = [i, j]; }
    }));
    out.push({ request: req, station: pick, score: best });
    return out;
  }, []);

  const nextTests = (() => {
    const A = M.map(r => r.slice());
    const total = N * W;
    const K = (C % (total || 1)) + 1;
    const seq = [];
    for (let x = 0; x < K; x++) {
      let mx = -Infinity, xi = 0, yj = 0;
      A.forEach((r, i) => r.forEach((v, j) => {
        if (v > mx) { mx = v; xi = i; yj = j; }
      }));
      seq.push([xi, yj]);
      A[xi][yj] = -Infinity;
    }
    return seq;
  })();

  const newMetrics = M.map(row => row.map(v => ( (v * 3 + C * C) % 101 )));

  return { assignments, nextTests, newMetrics };
}
