import dayjs from 'dayjs';
export function processData(input) {
  if (!input || typeof input !== 'object') return input;
  const tx = input.transactions || [], n = tx.length;
  const k = (Math.sqrt(n) + .999 | 0) || 1;
  let centers = tx.slice(0, k).map(r => r.amount), assignments = new Array(n).fill(0);
  let prev;
  for (let iter = 0; iter < 2; iter++) {
    prev = centers.slice();
    tx.forEach((r, i) => {
      assignments[i] = prev.reduce((best, v, j) => {
        const d = Math.abs(r.amount - v);
        return d < best[0] ? [d, j] : best;
      }, [Infinity, 0])[1];
    });
    centers = prev.map((v, j) => {
      const [sum, cnt] = tx.reduce(([s, c], r, i) => 
        assignments[i] === j ? [s + r.amount, c + 1] : [s, c]
      , [0, 0]);
      return cnt ? Math.round(sum / cnt) : v;
    });
  }
  const clusters = centers.map((c, j) => ({
    center: c,
    members: assignments.reduce((a, v, i) => v === j ? (a.push(i), a) : a, [])
  }));
  const forecasts = clusters.map(({ center, members }) => {
    if (members.length < 2) return { center, nextDate: null };
    const dates = members.map(i => dayjs(tx[i].date)).sort((a, b) => a - b);
    const total = dates.slice(1).reduce((s, d, i) => s + d.diff(dates[i], 'day'), 0);
    const avg = total / (dates.length - 1) | 0;
    return { center, nextDate: dates[dates.length - 1].add(avg, 'day').format('YYYY-MM-DD') };
  });
  const lookup = (input.lookupRequests || []).map(q => {
    const best = (input.translations || []).reduce((b, { src, tgt }) => {
      const sc = src.split('').reduce((s, c) => s + (q.includes(c) ? 1 : 0), 0);
      return sc > b[0] ? [sc, tgt] : b;
    }, [-1, null]);
    return { request: q, result: best[1] };
  });
  return { clusters, forecasts, lookup };
}
