from typing import List, Dict, Literal
from datetime import time
from pydantic import BaseModel, Field, model_validator, ValidationError

class TimeWindow(BaseModel):
    start: time
    end: time

    @model_validator(mode='after')
    def check_range(cls, tw):
        if tw.start >= tw.end:
            raise ValidationError(
                [
                    {
                        'loc': ('start',),
                        'msg': 'start must be before end',
                        'type': 'value_error'
                    }
                ],
                model=cls
            )
        return tw

class Discount(BaseModel):
    type: Literal['percentage', 'fixed']
    value: float = Field(gt=0)

    @model_validator(mode='after')
    def validate_value(cls, d):
        if d.type == 'percentage' and d.value > 100:
            raise ValidationError(
                [
                    {
                        'loc': ('value',),
                        'msg': 'percentage cannot exceed 100',
                        'type': 'value_error'
                    }
                ],
                model=cls
            )
        return d

class HappyHourRule(BaseModel):
    days: List[Literal['Mon','Tue','Wed','Thu','Fri','Sat','Sun']]
    window: TimeWindow
    discount: Discount

    @model_validator(mode='after')
    def unique_days(cls, hhr):
        if len(set(hhr.days)) != len(hhr.days):
            raise ValidationError(
                [
                    {
                        'loc': ('days',),
                        'msg': 'duplicate days not allowed',
                        'type': 'value_error'
                    }
                ],
                model=cls
            )
        return hhr

class Ingredient(BaseModel):
    name: str
    amount_ml: float = Field(gt=0)

class Cocktail(BaseModel):
    name: str
    base_price: float = Field(gt=0)
    ingredients: List[Ingredient]

    @model_validator(mode='before')
    def check_ingredients_nonempty(cls, data):
        if 'ingredients' in data and not data['ingredients']:
            raise ValidationError(
                [
                    {
                        'loc': ('ingredients',),
                        'msg': 'must have at least one ingredient',
                        'type': 'value_error'
                    }
                ],
                model=cls
            )
        return data

class PricingRules(BaseModel):
