from typing import List, Dict, Optional, Union
from pydantic import BaseModel, Field, field_validator, model_validator, ValidationError, StrictStr, StrictInt, StrictFloat, StrictBool, Extra
import re

class WrapperSpec(BaseModel):
    name: StrictStr
    params: Dict[StrictStr, Union[StrictStr, StrictInt, StrictFloat, StrictBool]] = Field(default_factory=dict)

    model_config = {"extra": Extra.forbid}

    @field_validator('name')
    @classmethod
    def validate_name(cls, v):
        if not v.isidentifier():
            raise ValidationError('wrapper name must be a valid identifier', cls)
        return v

    @field_validator('params', mode='before')
    @classmethod
    def validate_params(cls, v):
        if not isinstance(v, dict):
            raise ValidationError('params must be a dict', cls)
        for k in v:
            if not isinstance(k, str) or k.startswith('_'):
                raise ValidationError('param keys must be non-private strings', cls)
        return v

class EnvSpec(BaseModel):
    env_id: StrictStr
    entry_point: StrictStr
    max_episode_steps: Optional[StrictInt] = None
    reward_threshold: Optional[StrictFloat] = None
    wrappers: List[WrapperSpec] = Field(default_factory=list)
    kwargs: Dict[StrictStr, Union[StrictStr, StrictInt, StrictFloat, StrictBool]] = Field(default_factory=dict)

    model_config = {"extra": Extra.forbid}

    @field_validator('env_id')
    @classmethod
    def validate_env_id(cls, v):
        if ':' in v or ' ' in v:
            raise ValidationError('env_id must not contain colon or spaces', cls)
        return v

    @field_validator('entry_point')
    @classmethod
    def validate_entry_point(cls, v):
        pattern = r'^[\w\.]+:[\w_]+$'
        if not re.match(pattern, v):
            raise ValidationError('entry_point must be in "module.sub:func" format', cls)
        return v

    @field_validator('max_episode_steps')
    @classmethod
    def validate_max_steps(cls, v):
        if v is not None and v <= 0:
            raise ValidationError('max_episode_steps must be positive', cls)
        return v

    @field_validator('reward_threshold')
    @classmethod
    def validate_reward_threshold(cls, v):
        if v is not None and v < 0:
            raise ValidationError('reward_threshold must be non-negative', cls)
        return v

    @model_validator(mode='after')
    @classmethod
    def check_consistency(cls, values):
        if values.reward_threshold is not None and values.max_episode_steps is None:
            raise ValidationError('reward_threshold provided without max_episode_steps', cls)
        names = [w.name for w in values.wrappers]
        if len(names) != len(set(names)):
            raise ValidationError('wrapper names must be unique', cls)
        return values

class EnvRegistry(BaseModel):
    version: StrictInt
    entries: List[EnvSpec]
    metadata: Dict[StrictStr, StrictStr] = Field(default_factory=dict)

    model_config = {"extra": Extra.forbid}

    @field_validator('version')
    @classmethod
    def validate_version(cls, v):
        if v <= 0:
            raise ValidationError('version must be > 0', cls)
        return v

    @field_validator('metadata', mode='before')
    @classmethod
    def validate_metadata(cls, v):
        if not isinstance(v, dict):
            raise ValidationError('metadata must be a dict', cls)
        for k in v:
            if not isinstance(k, str) or not k.isidentifier():
                raise ValidationError('metadata keys must be valid identifiers', cls)
        return v

    @model_validator(mode='after')
    @classmethod
    def check_entries(cls, values):
        if not values.entries:
            raise ValidationError('entries list cannot be empty', cls)
        ids = [e.env_id for e in values.entries]
        if len(ids) != len(set(ids)):
            raise ValidationError('env_id values in entries must be unique', cls)
        return values

